// Monta o rótulo de prazo de cada documento ativo do cliente
public List<string> ObterRotulosPrazo(List<Documento> documentos, DateTime hoje)
{
    return documentos
        .Where(d => d.Ativo)
        .OrderBy(d => d.DataVencimento)
        .Select(d => (d.DataVencimento - hoje).Days switch
        {
            < 0 => $"{d.Nome}: vencido",
            0 => $"{d.Nome}: vence hoje",
            <= 7 => $"{d.Nome}: vence em {(d.DataVencimento - hoje).Days} dias",
            _ => $"{d.Nome}: no prazo"
        })
        .ToList();
}

