// Salva as classificações do documento e registra o log da alteração
public async Task<Retorno> SalvarClassificacoes(string documentoId, List<string> classificacoes)
{
    var documento = await _documentoRepository.ObterPorId(documentoId);
    if (documento == null)
        return Retorno.Erro("Documento não encontrado");

    foreach (var classificacao in classificacoes)
    {
        _classificacaoRepository.Inserir(documentoId, classificacao);
    }

    _logRepository.Registrar(documentoId, "Classificações alteradas");

    return Retorno.Ok();
}

