// Monta o texto do responsável para o cabeçalho do cliente
public string ObterTextoResponsavel(Cliente? cliente)
{
    var nome = cliente?.Responsavel?.Nome ?? "";

    return cliente == null ? "Cliente não encontrado"
        : !cliente.Ativo ? "Cliente inativo"
        : nome != "" ? $"Responsável: {nome}"
        : "Sem responsável";
}

